template:
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
enum AppError {
    InvalidNumber,
}

fn parse_id(s: &str) -> Result<i32, AppError> {
    let id = s
        .parse::<i32>()
        ⟦slot1⟧⟦slot2⟧;
    Ok(id)
}

fn main() {
    let _ = parse_id("123");
}

tests:
#[test]
fn test_parse() {
    assert_eq!(parse_id("42"), Ok(42));
    assert_eq!(parse_id("abc"), Err(AppError::InvalidNumber));
}
